async function load(){try{const response=await fetch(`latest.json?t=${Date.now()}`,{cache:"no-store"});if(!response.ok)throw new Error("数据载入失败");const data=await response.json(),select=document.querySelector("#assetSelect");select.innerHTML=data.assets.map(asset=>`<option value="${asset.id}">${escapeHtml(asset.name)} · ${asset.symbol}</option>`).join("");const requested=new URLSearchParams(location.search).get("id"),asset=data.assets.find(item=>item.id===requested&&item.status!=="missing")||data.assets.find(item=>item.status!=="missing");select.value=asset.id;select.addEventListener("change",()=>{location.href=`asset.html?id=${encodeURIComponent(select.value)}`});renderAsset(data,asset)}catch(error){document.querySelector("#assetSubtitle").textContent=error.message}}
